/* Supabase cloud bridge. Offline source is kept separately. */
window.TMCloud=(()=>{
 const url='https://vcvqoonpcojnlidqhwmp.supabase.co',key='sb_publishable_WDVIIs8ZnOe95NysIFUpEw_RdnuImAB';
 const rawSet=Storage.prototype.setItem,rawRemove=Storage.prototype.removeItem;
 const mapping={amc_technicians:['technician','array'],amc_day_allocations:['allocation_day','days'],amc_callouts:['callout','array'],amc_leaves:['leave','array'],amc_leave_requests:['leave_request','array'],amc_overtime_records:['overtime','array'],amc_bahrain_holidays:['holiday','array'],amc_saturday_settings:['saturday_settings','single'],amc_callout_roster:['callout_roster','single'],amc_team_settings:['team_settings','single']};
 let versions={},baseline={},pending=Promise.resolve(),dirty=0,failed=false,refreshing=null,terminating=false,guardInstalled=false,installed=false,syncing=false,revision=0;
 const readSession=()=>{try{return JSON.parse(sessionStorage.getItem('amc_auth_session')||localStorage.getItem('amc_auth_session')||'null')}catch{return null}};
 const profile=p=>({id:p.id,username:p.username,name:p.name,role:p.role,status:p.status,technicianNumber:p.technician_id||'',createdAt:p.created_at});
 const banner=(text,error=false)=>{if(!error&&/^(Connected to Supabase|Saving changes to Supabase|Saved to Supabase)/.test(text))return;let el=document.getElementById('cloud-status');if(!el){el=document.createElement('div');el.id='cloud-status';el.setAttribute('role','status');el.style.cssText='position:fixed;bottom:12px;left:12px;z-index:99999;padding:10px 14px;border-radius:8px;font:13px system-ui;max-width:calc(100vw - 24px);box-sizing:border-box';document.body.append(el)}el.textContent=text;el.style.background=error?'#9f2020':'#145c4a';el.style.color='white';el.hidden=false;clearTimeout(el.dismissTimer);if(!error&&!text.startsWith('Saving'))el.dismissTimer=setTimeout(()=>{el.hidden=true;},6000);};
 function showCredentials(accounts){if(!accounts?.length)return;const overlay=document.createElement('div');overlay.className='cloud-credential-overlay';const dialog=document.createElement('section');dialog.className='cloud-credential-dialog';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label','New technician logins');const title=document.createElement('h2');title.textContent='Technician logins created';const hint=document.createElement('p');hint.textContent='Copy these credentials before closing. Generated passwords are shown only once.';const text=accounts.map(a=>a.name+' (ID '+a.technician_id+')\nUsername: '+a.username+'\nPassword: '+a.password).join('\n\n');const details=document.createElement('pre');details.textContent=text;const actions=document.createElement('div');actions.className='cloud-credential-actions';const copy=document.createElement('button');copy.className='btn btn-primary';copy.textContent='Copy credentials';copy.onclick=async()=>{try{await navigator.clipboard.writeText(text);copy.textContent='Copied';}catch{copy.textContent='Select and copy the text above';}};const close=document.createElement('button');close.className='btn btn-outline';close.textContent='Done';close.onclick=()=>overlay.remove();actions.append(copy,close);dialog.append(title,hint,details,actions);overlay.append(dialog);document.body.append(overlay);copy.focus();}
 function authError(message){const error=Error(message);error.code='AUTH_REQUIRED';return error;}
 function clearSession(){rawRemove.call(localStorage,'amc_auth_session');rawRemove.call(sessionStorage,'amc_auth_session');}
 function signOut(reason='Your session ended. Please sign in again.',broadcast=true){
  if(terminating)return;terminating=true;const session=readSession();clearSession();
  for(const k of [...Object.keys(mapping),'amc_system_users','amc_technician_directory','amc_overtime_invitations'])rawRemove.call(localStorage,k);
  if(session?.user?.id&&broadcast)rawSet.call(localStorage,'amc_signout_'+session.user.id,String(Date.now()));
  rawSet.call(sessionStorage,'amc_signout_reason',reason);
  if(session?.token)fetch(url+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:key,Authorization:'Bearer '+session.token},keepalive:true}).catch(()=>{});
  location.reload();
 }
 function reconnect(error){if(error.code==='AUTH_REQUIRED')signOut(error.message);}
 function installSessionGuard(){
  if(guardInstalled)return;guardInstalled=true;const session=readSession();if(!session?.cloud)return;
  const activityKey='amc_activity_'+session.user.id,logoutKey='amc_signout_'+session.user.id,idleLimit=5*60*1000;
  let lastActivity=Number(localStorage.getItem(activityKey))||Date.now(),checking=false;
  const checkIdle=()=>{lastActivity=Math.max(lastActivity,Number(localStorage.getItem(activityKey))||0);if(Date.now()-lastActivity>=idleLimit){signOut('Signed out after 5 minutes of inactivity.');return false;}return !terminating;};
  const activity=()=>{const now=Date.now();if(now-lastActivity<1000||!checkIdle())return;lastActivity=now;rawSet.call(localStorage,activityKey,String(now));};
  if(!checkIdle())return;rawSet.call(localStorage,activityKey,String(lastActivity));
  for(const event of ['pointerdown','pointermove','keydown','scroll','touchstart'])window.addEventListener(event,activity,{capture:true,passive:true});
  const checkAccount=async()=>{if(checking||!checkIdle()||!readSession()?.cloud)return;checking=true;try{await api('me');}catch(error){reconnect(error);}finally{checking=false;}};
  setInterval(checkIdle,1000);setInterval(checkAccount,15000);
  window.addEventListener('focus',checkAccount);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkAccount();});
  window.addEventListener('storage',event=>{if(event.key===logoutKey)signOut('Your session ended. Please sign in again.',false);if(event.key==='amc_auth_session'&&!event.newValue)signOut('You have been signed out.',false);});
 }
 function persist(session){if(terminating)return;const target=localStorage.getItem('amc_auth_session')?localStorage:sessionStorage;rawSet.call(target,'amc_auth_session',JSON.stringify(session));}
 async function renew(){if(refreshing)return refreshing;refreshing=(async()=>{const s=readSession();if(!s?.refresh_token)throw authError('Please sign in to continue.');const r=await fetch(url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json();if(!r.ok){if(r.status===400||r.status===401||r.status===403)throw authError('Your session expired. Please sign in again.');throw Error('Cannot refresh the connection. Please try again.');}const next={...s,token:d.access_token,refresh_token:d.refresh_token,expires_at:d.expires_at};persist(next);return next;})().finally(()=>refreshing=null);return refreshing;}
 async function api(action,body={},retry=true){let session=action==='login'?null:readSession();if(action!=='login'&&(terminating||!session?.cloud))throw authError('Please sign in to continue.');if(action!=='login'&&session?.expires_at&&session.expires_at*1000<Date.now()+60000){try{session=await renew();}catch(error){reconnect(error);throw error;}}if(action!=='login'&&terminating)throw authError('Please sign in again.');const r=await fetch(url+'/functions/v1/tm-api',{method:'POST',headers:{apikey:key,'Content-Type':'application/json',...(session?.token?{Authorization:'Bearer '+session.token}:{})},body:JSON.stringify({action,...body}),signal:AbortSignal.timeout(25000)});const d=await r.json().catch(()=>({error:'Cloud service is not deployed or returned an invalid response.'}));if(r.status===403&&d.error==='Account inactive'){signOut('Your account has been deleted or suspended.');throw authError('Account inactive');}if(r.status===401&&action!=='login'&&retry){try{await renew();}catch(error){reconnect(error);throw error;}return api(action,body,false)}if(r.status===401&&action!=='login'){const error=authError('Your session expired. Please sign in again.');reconnect(error);throw error;}if(!r.ok)throw Error(d.error||'Cloud request failed');return d;}
 const entries=(value,shape)=>shape==='days'?Object.entries(value||{}):shape==='single'?[['default',value||{}]]:(value||[]).map(r=>[String(r.id),r]);
 const materialize=snapshot=>{const values={};for(const [k,[kind,shape]] of Object.entries(mapping)){const records=snapshot.records.filter(r=>r.kind===kind);values[k]=shape==='days'?Object.fromEntries(records.map(r=>[r.id,r.payload])):shape==='single'?(records[0]?.payload||{}):records.map(r=>r.payload);}return values;};
 const stable=value=>Array.isArray(value)?value.map(stable):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(key=>[key,stable(value[key])])):value;
 const stableList=value=>JSON.stringify(stable([...(value||[])].sort((a,b)=>String(a.id).localeCompare(String(b.id)))));
 const dataSignature=values=>JSON.stringify(stable(Object.fromEntries(Object.entries(mapping).map(([key,[,shape]])=>[key,shape==='array'?[...(values[key]||[])].sort((a,b)=>String(a.id).localeCompare(String(b.id))):values[key]]))));
 const deferSync=()=>dirty||failed||document.hidden||document.activeElement?.matches('input,textarea,[contenteditable=true]')||document.querySelector('.modal-backdrop,.modal-overlay,.cloud-credential-overlay,[data-floating-panel]');
 function hydrate(snapshot){if(terminating)return {};const values=materialize(snapshot);versions={};snapshot.records.forEach(r=>versions[r.kind+':'+r.id]=r.version);for(const [k,v] of Object.entries(values)){rawSet.call(localStorage,k,JSON.stringify(v));baseline[k]=v;}rawSet.call(localStorage,'amc_system_users',JSON.stringify(snapshot.users.map(profile)));rawSet.call(localStorage,'amc_technician_directory',JSON.stringify(snapshot.technicians||[]));rawSet.call(localStorage,'amc_overtime_invitations',JSON.stringify(snapshot.overtimeInvitations||[]));const s=readSession();if(s)persist({...s,user:profile(snapshot.profile)});return values;}
 function install(){if(installed)return;installed=true;Storage.prototype.setItem=function(k,v){if(this!==localStorage||!mapping[k])return rawSet.call(this,k,v);const next=JSON.parse(v),[kind,shape]=mapping[k],previous=new Map(entries(baseline[k],shape)),incoming=new Map(entries(next,shape));const changes=[];for(const [id,payload] of incoming)if(JSON.stringify(payload)!==JSON.stringify(previous.get(id)))changes.push({kind,id,payload});for(const id of previous.keys())if(!incoming.has(id))changes.push({kind,id,deleted:true});rawSet.call(this,k,v);baseline[k]=next;if(!changes.length)return;revision++;dirty++;banner('Saving changes to Supabase…');pending=pending.then(async()=>{if(failed)throw Error('A previous save failed. Keep this tab open and resolve it before continuing.');for(const c of changes){const result=await api('save_record',{...c,version:versions[kind+':'+c.id]||0});if(c.kind==='technician'&&c.deleted){const removed=new Set(result.record?.deleted_user_ids||[]);const users=JSON.parse(localStorage.getItem('amc_system_users')||'[]');rawSet.call(localStorage,'amc_system_users',JSON.stringify(users.filter(user=>!removed.has(user.id))));const directory=JSON.parse(localStorage.getItem('amc_technician_directory')||'[]');rawSet.call(localStorage,'amc_technician_directory',JSON.stringify(directory.filter(tech=>String(tech.id)!==String(c.id))));}if(result.credentials?.length)showCredentials(result.credentials);if(result.accountWarning)banner(result.accountWarning,true);if(c.deleted)delete versions[kind+':'+c.id];else versions[kind+':'+c.id]=result.record.version;}}).then(()=>{dirty--;banner(dirty?'Saving changes to Supabase…':'Saved to Supabase');}).catch(error=>{failed=true;dirty--;if(terminating)return;banner('NOT SAVED: '+error.message+' Your local edits remain in this tab.',true);});};
  window.addEventListener('beforeunload',e=>{if(!terminating&&(dirty||failed)){e.preventDefault();e.returnValue=''}});
  setInterval(async()=>{
   if(syncing||terminating||!readSession()?.cloud||deferSync())return;
   syncing=true;const startedRevision=revision;
   try{
    const snapshot=await api('snapshot');
    if(terminating||deferSync()||startedRevision!==revision)return;
    const next=materialize(snapshot),users=snapshot.users.map(profile);snapshot.records.forEach(record=>versions[record.kind+':'+record.id]=record.version);
    if(stableList(snapshot.overtimeInvitations||[])!==stableList(JSON.parse(localStorage.getItem('amc_overtime_invitations')||'[]'))||dataSignature(next)!==dataSignature(baseline)||stableList(snapshot.technicians)!==stableList(JSON.parse(localStorage.getItem('amc_technician_directory')||'[]'))||stableList(users)!==stableList(JSON.parse(localStorage.getItem('amc_system_users')||'[]'))){
     const values=hydrate(snapshot);window.dispatchEvent(new CustomEvent('tm-cloud-update',{detail:{values,user:profile(snapshot.profile)}}));
    }
   }catch(error){if(error.code==='AUTH_REQUIRED'){reconnect(error);return;}banner('Cloud connection: '+error.message,true);}
   finally{syncing=false;}
  },15000);
 }
 async function start(){const s=readSession();if(!s?.cloud){for(const k of [...Object.keys(mapping),'amc_system_users','amc_technician_directory','amc_overtime_invitations'])rawRemove.call(localStorage,k);const reason=sessionStorage.getItem('amc_signout_reason');if(reason){rawRemove.call(sessionStorage,'amc_signout_reason');banner(reason);}return;}installSessionGuard();if(terminating)return;try{hydrate(await api('snapshot'));install();banner('Connected to Supabase');}catch(error){if(error.code==='AUTH_REQUIRED'){reconnect(error);return;}banner(error.message,true);}}
 async function login(username,password,remember){
  const d=await api('login',{username,password});
  const session={cloud:true,user:profile(d.profile),token:d.session.access_token,refresh_token:d.session.refresh_token,expires_at:d.session.expires_at,createdAt:new Date().toISOString()};
  rawRemove.call(localStorage,'amc_auth_session');rawRemove.call(sessionStorage,'amc_auth_session');rawSet.call(remember?localStorage:sessionStorage,'amc_auth_session',JSON.stringify(session));rawSet.call(localStorage,'amc_activity_'+session.user.id,String(Date.now()));
  try{const snapshot=await api('snapshot');const values=hydrate(snapshot);install();installSessionGuard();window.dispatchEvent(new CustomEvent('tm-cloud-update',{detail:{values,user:profile(snapshot.profile)}}));return readSession();}
  catch(error){clearSession();throw error;}
 }
 async function changePassword(password){
  await api('me');const session=readSession();if(terminating||!session?.token)throw authError('Please sign in again.');
  const response=await fetch(url+'/auth/v1/user',{method:'PUT',headers:{apikey:key,'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({password}),signal:AbortSignal.timeout(25000)});
  const result=await response.json().catch(()=>({}));
  if(response.status===401){signOut('Your session expired. Please sign in again.');throw authError('Session expired');}
  if(!response.ok)throw Error(result.msg||result.message||result.error_description||'Could not update your password. Please try again.');
 }
 async function refresh(){await pending;if(dirty||failed)throw Error('Finish saving your current changes before refreshing.');const startedRevision=revision;const snapshot=await api('snapshot');if(dirty||startedRevision!==revision)throw Error('Your changes are saving. The new records will appear after synchronization.');const values=hydrate(snapshot);window.dispatchEvent(new CustomEvent('tm-cloud-update',{detail:{values,user:profile(snapshot.profile)}}));return snapshot;}
 return {start,login,api,refresh,banner,profile,showCredentials,changePassword,signOut,recordVersion:(kind,id)=>versions[kind+':'+id]||0};
})();
